import{_ as a,c as t,o as s,ag as i}from"./chunks/framework.Bzez9NG9.js";const p=JSON.parse('{"title":"AI configuration","description":"Understand SPACE AI profiles, provider and model configuration, response settings, and the system defaults used when profile values are not set.","frontmatter":{"title":"AI configuration","description":"Understand SPACE AI profiles, provider and model configuration, response settings, and the system defaults used when profile values are not set.","keywords":["temperature","token limits","credentials"],"outline":"deep"},"headers":[],"relativePath":"doc/configuration/ai.md","filePath":"doc/configuration/ai.md"}'),o={name:"doc/configuration/ai.md"};function n(r,e,l,d,c,f){return s(),t("div",null,e[0]||(e[0]=[i('<h1 id="ai-configuration" tabindex="-1">AI configuration <a class="header-anchor" href="#ai-configuration" aria-label="Permalink to &quot;AI configuration&quot;">​</a></h1><p>Open <strong>SPACE settings → AI</strong> to manage AI profiles. Profiles define how the assistant connects to an AI provider and how responses are generated. Administrators can configure profiles, available models, and assistant behavior for their deployment.</p><p>For using the assistant and asking questions about TM1 models, see <a href="./../ai/">AI Assistant</a>.</p><h2 id="ai-profiles" tabindex="-1">AI profiles <a class="header-anchor" href="#ai-profiles" aria-label="Permalink to &quot;AI profiles&quot;">​</a></h2><p>Profile settings may include:</p><ul><li>Provider.</li><li>Model.</li><li>Maximum input tokens.</li><li>Maximum output tokens.</li><li>Temperature.</li><li>Connection credentials or provider configuration.</li></ul><h2 id="system-defaults" tabindex="-1">System defaults <a class="header-anchor" href="#system-defaults" aria-label="Permalink to &quot;System defaults&quot;">​</a></h2><p>If input token, output token, or temperature fields are left empty, SPACE uses the corresponding <a href="./system-settings.html#ai-profile-defaults">AI profile defaults</a> from <strong>SPACE settings → Configuration</strong>.</p><p>Profile-specific values and shared defaults are configured in these separate settings areas.</p><h2 id="access" tabindex="-1">Access <a class="header-anchor" href="#access" aria-label="Permalink to &quot;Access&quot;">​</a></h2><p>The assistant operates through SPACE permissions and IBM Planning Analytics access controls. See <a href="./access.html">Access</a> for SPACE users and roles and <a href="./connections.html">Connections</a> for connection access restrictions.</p>',11)]))}const h=a(o,[["render",n]]);export{p as __pageData,h as default};
